import{_ as e,o as s,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"Renode Emulation Guide: Hardware-Free Embedded Linux Development","description":"","frontmatter":{},"headers":[],"relativePath":"renode-emulation-guide.md","filePath":"renode-emulation-guide.md"}'),t={name:"renode-emulation-guide.md"};function r(o,a,d,l,p,h){return s(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="renode-emulation-guide-hardware-free-embedded-linux-development" tabindex="-1">Renode Emulation Guide: Hardware-Free Embedded Linux Development <a class="header-anchor" href="#renode-emulation-guide-hardware-free-embedded-linux-development" aria-label="Permalink to &quot;Renode Emulation Guide: Hardware-Free Embedded Linux Development&quot;">​</a></h1><div style="background:linear-gradient(135deg, #00c6ff 0%, #0072ff 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Purpose</strong></p><p>This guide enables you to practice embedded Linux development on <strong>Zynq-7000 (ZedBoard/PYNQ)</strong> targets without purchasing physical hardware, using <a href="https://renode.io" target="_blank" rel="noreferrer">Renode</a> — an open-source hardware emulator developed by <a href="https://antmicro.com" target="_blank" rel="noreferrer">Antmicro</a>.</p></div><hr><h2 id="_1-what-is-renode" tabindex="-1">1. What is Renode? <a class="header-anchor" href="#_1-what-is-renode" aria-label="Permalink to &quot;1. What is Renode?&quot;">​</a></h2><p><strong>Renode</strong> is an open-source instruction set simulator and hardware emulation framework. Unlike QEMU (which focuses primarily on CPU emulation), Renode was designed to emulate <strong>complete embedded systems</strong> including:</p><ul><li>ARM Cortex-A/R/M processors, RISC-V, PowerPC, Xtensa, SPARC</li><li>Peripheral models: UART, I2C, SPI, GPIO, Timer, Ethernet, DMA</li><li>Board-level platform descriptions (<code>.repl</code> files) mapping peripherals to memory addresses</li><li>Multi-node simulations (emulating networks of interconnected devices)</li></ul><h3 id="renode-vs-qemu-when-to-use-what" tabindex="-1">Renode vs QEMU: When to Use What <a class="header-anchor" href="#renode-vs-qemu-when-to-use-what" aria-label="Permalink to &quot;Renode vs QEMU: When to Use What&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Renode</th><th>QEMU (via Yocto <code>runqemu</code>)</th></tr></thead><tbody><tr><td><strong>Zynq-7000 / ZedBoard Support</strong></td><td>✅ Native platform description</td><td>❌ Not supported</td></tr><tr><td><strong>BeagleBone Black (AM335x)</strong></td><td>❌ Not supported</td><td>✅ via <code>qemuarm</code></td></tr><tr><td><strong>Raspberry Pi</strong></td><td>❌ Not supported</td><td>✅ via <code>qemuarm64</code></td></tr><tr><td><strong>Peripheral Emulation</strong></td><td>Full (UART, I2C, SPI, GPIO, Timer)</td><td>Partial (virtio devices)</td></tr><tr><td><strong>Multi-Device Simulation</strong></td><td>✅ Network of connected boards</td><td>Limited</td></tr><tr><td><strong>GDB Integration</strong></td><td>✅ Built-in GDB server</td><td>✅ via <code>-s -S</code> flags</td></tr><tr><td><strong>Yocto Integration</strong></td><td>Manual (load kernel + rootfs)</td><td>Automatic (<code>runqemu</code>)</td></tr><tr><td><strong>Install Complexity</strong></td><td>Medium (mono/.NET runtime required)</td><td>Low (bundled with Poky)</td></tr></tbody></table><hr><h2 id="_2-installing-renode" tabindex="-1">2. Installing Renode <a class="header-anchor" href="#_2-installing-renode" aria-label="Permalink to &quot;2. Installing Renode&quot;">​</a></h2><h3 id="ubuntu-debian-recommended" tabindex="-1">Ubuntu/Debian (Recommended) <a class="header-anchor" href="#ubuntu-debian-recommended" aria-label="Permalink to &quot;Ubuntu/Debian (Recommended)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Download the latest Renode .deb package</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/renode/renode/releases/latest/download/renode_</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.deb</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install (installs mono runtime dependency automatically)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./renode_</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.deb</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Verify installation</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">renode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h3 id="from-binary-release-alternative" tabindex="-1">From Binary Release (Alternative) <a class="header-anchor" href="#from-binary-release-alternative" aria-label="Permalink to &quot;From Binary Release (Alternative)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Download portable release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/renode/renode/releases/latest/download/renode-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.linux-portable.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> renode-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.linux-portable.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> renode_</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add to PATH</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD:$PATH</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">renode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><hr><h2 id="_3-core-renode-concepts" tabindex="-1">3. Core Renode Concepts <a class="header-anchor" href="#_3-core-renode-concepts" aria-label="Permalink to &quot;3. Core Renode Concepts&quot;">​</a></h2><h3 id="_3-1-platform-description-files-repl" tabindex="-1">3.1 Platform Description Files (<code>.repl</code>) <a class="header-anchor" href="#_3-1-platform-description-files-repl" aria-label="Permalink to &quot;3.1 Platform Description Files (\`.repl\`)&quot;">​</a></h3><p>A <code>.repl</code> (Renode Platform) file describes the hardware architecture of a board: which CPU, what peripherals exist, and how they are mapped into the memory address space.</p><p>Example excerpt from <code>zedboard.repl</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cpu: CPU.ARMv7A @ sysbus</span></span>
<span class="line"><span>    cpuType: &quot;cortex-a9&quot;</span></span>
<span class="line"><span>    genericInterruptController: gic</span></span>
<span class="line"><span></span></span>
<span class="line"><span>uart0: UART.Cadence @ sysbus 0xE0000000</span></span>
<span class="line"><span>    -&gt; gic@59</span></span>
<span class="line"><span></span></span>
<span class="line"><span>uart1: UART.Cadence @ sysbus 0xE0001000</span></span>
<span class="line"><span>    -&gt; gic@82</span></span></code></pre></div><h3 id="_3-2-script-files-resc" tabindex="-1">3.2 Script Files (<code>.resc</code>) <a class="header-anchor" href="#_3-2-script-files-resc" aria-label="Permalink to &quot;3.2 Script Files (\`.resc\`)&quot;">​</a></h3><p>A <code>.resc</code> (Renode Script) file automates the setup process: creating machines, loading platform descriptions, configuring binaries, and starting the simulation.</p><h3 id="_3-3-the-monitor-cli" tabindex="-1">3.3 The Monitor CLI <a class="header-anchor" href="#_3-3-the-monitor-cli" aria-label="Permalink to &quot;3.3 The Monitor CLI&quot;">​</a></h3><p>Renode provides an interactive command-line interface (the <strong>Monitor</strong>) where you can:</p><ul><li>Create and configure machines</li><li>Load binaries (ELF, raw binary, device tree)</li><li>Start/pause/step execution</li><li>Inspect registers, memory, and peripheral state</li><li>Connect UART analyzers (virtual serial terminals)</li></ul><hr><h2 id="_4-running-linux-on-zedboard-in-renode" tabindex="-1">4. Running Linux on ZedBoard in Renode <a class="header-anchor" href="#_4-running-linux-on-zedboard-in-renode" aria-label="Permalink to &quot;4. Running Linux on ZedBoard in Renode&quot;">​</a></h2><p>The ZedBoard is based on the <strong>Xilinx Zynq-7000 SoC</strong> (dual-core ARM Cortex-A9 + FPGA fabric). Renode includes a ready-to-use script for this platform.</p><h3 id="_4-1-quick-start-with-built-in-demo" tabindex="-1">4.1 Quick Start with Built-in Demo <a class="header-anchor" href="#_4-1-quick-start-with-built-in-demo" aria-label="Permalink to &quot;4.1 Quick Start with Built-in Demo&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Launch Renode</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">renode</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In the Renode Monitor, load the ZedBoard script:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">monitor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @scripts/single-node/zedboard.resc</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start the simulation</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">monitor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start</span></span></code></pre></div><p>This loads a pre-built Linux kernel and rootfs from Antmicro&#39;s servers and boots into a Linux shell via the virtual UART.</p><h3 id="_4-2-loading-your-own-yocto-image" tabindex="-1">4.2 Loading Your Own Yocto Image <a class="header-anchor" href="#_4-2-loading-your-own-yocto-image" aria-label="Permalink to &quot;4.2 Loading Your Own Yocto Image&quot;">​</a></h3><p>After building a Yocto image for <code>MACHINE = &quot;zedboard-zynq7&quot;</code> or a generic Zynq target, you can load your custom kernel and rootfs into Renode:</p><p><strong>Step 1: Build a Yocto image for Zynq</strong></p><p>You&#39;ll need the <code>meta-xilinx</code> BSP layer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kirkstone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git://git.yoctoproject.org/meta-xilinx</span></span></code></pre></div><p>Add to <code>bblayers.conf</code> and set in <code>local.conf</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MACHINE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;zedboard-zynq7&quot;</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core-image-minimal</span></span></code></pre></div><p><strong>Step 2: Create a custom Renode script</strong></p><p>Create a file <code>my-zedboard.resc</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:name: MyZedBoard</span></span>
<span class="line"><span>:description: Custom Yocto Linux on ZedBoard</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using sysbus</span></span>
<span class="line"><span>mach create &quot;MyZedBoard&quot;</span></span>
<span class="line"><span>machine LoadPlatformDescription @platforms/boards/zedboard.repl</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Show UART terminal</span></span>
<span class="line"><span>showAnalyzer uart0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Redirect memory region (required for Zynq boot)</span></span>
<span class="line"><span>sysbus Redirect 0xC0000000 0x0 0x10000000</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Load your Yocto-built kernel (vmlinux ELF format)</span></span>
<span class="line"><span>$bin = @/path/to/tmp/deploy/images/zedboard-zynq7/vmlinux</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Load device tree</span></span>
<span class="line"><span>$dtb = @/path/to/tmp/deploy/images/zedboard-zynq7/zynq-zed.dtb</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Load rootfs (ext2/ext4 image)</span></span>
<span class="line"><span>$rootfs = @/path/to/tmp/deploy/images/zedboard-zynq7/core-image-minimal-zedboard-zynq7.ext4</span></span></code></pre></div><p><strong>Step 3: Run it</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">renode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-zedboard.resc</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">monitor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start</span></span></code></pre></div><hr><h2 id="_5-debugging-with-renode-gdb" tabindex="-1">5. Debugging with Renode + GDB <a class="header-anchor" href="#_5-debugging-with-renode-gdb" aria-label="Permalink to &quot;5. Debugging with Renode + GDB&quot;">​</a></h2><p>Renode includes a built-in GDB server, allowing you to attach <code>arm-poky-linux-gnueabi-gdb</code> for source-level debugging of kernel or userspace applications:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In Renode Monitor:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">monitor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">machine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> StartGdbServer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3333</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In a separate terminal, connect GDB:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-poky-linux-gnueabi-gdb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vmlinux</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :3333</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">break</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_kernel</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">continue</span></span></code></pre></div><hr><h2 id="_6-qemu-alternatives-for-non-zynq-boards" tabindex="-1">6. QEMU Alternatives for Non-Zynq Boards <a class="header-anchor" href="#_6-qemu-alternatives-for-non-zynq-boards" aria-label="Permalink to &quot;6. QEMU Alternatives for Non-Zynq Boards&quot;">​</a></h2><p>For boards not supported by Renode, use Yocto&#39;s built-in QEMU:</p><table tabindex="0"><thead><tr><th>Target Board</th><th>QEMU Machine</th><th>Command</th></tr></thead><tbody><tr><td>BeagleBone Black (AM335x)</td><td><code>qemuarm</code></td><td><code>runqemu qemuarm nographic</code></td></tr><tr><td>Raspberry Pi 3/4</td><td><code>qemuarm64</code></td><td><code>runqemu qemuarm64 nographic</code></td></tr><tr><td>Generic x86_64</td><td><code>qemux86-64</code></td><td><code>runqemu qemux86-64 nographic</code></td></tr><tr><td>Generic MIPS</td><td><code>qemumips</code></td><td><code>runqemu qemumips nographic</code></td></tr></tbody></table><hr><h2 id="_7-further-reading" tabindex="-1">7. Further Reading <a class="header-anchor" href="#_7-further-reading" aria-label="Permalink to &quot;7. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Renode Documentation</td><td><a href="https://renode.readthedocs.io/en/latest/" target="_blank" rel="noreferrer">renode.readthedocs.io</a></td></tr><tr><td>Renode GitHub Repository</td><td><a href="https://github.com/renode/renode" target="_blank" rel="noreferrer">github.com/renode/renode</a></td></tr><tr><td>Supported Boards &amp; Peripherals</td><td><a href="https://renode.readthedocs.io/en/latest/introduction/supported-boards.html" target="_blank" rel="noreferrer">renode.readthedocs.io/supported-boards</a></td></tr><tr><td>ZedBoard Script Source</td><td><a href="https://github.com/renode/renode/blob/master/scripts/single-node/zedboard.resc" target="_blank" rel="noreferrer">zedboard.resc</a></td></tr><tr><td>Antmicro Blog: Renode Tutorials</td><td><a href="https://antmicro.com/blog/tags/renode/" target="_blank" rel="noreferrer">antmicro.com/blog</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/07-zynq-yocto-dtc-tutorial-guide">← Zynq Curriculum Guide</a><a href="/glossary">Glossary of Terms →</a></div>`,57)])])}const g=e(t,[["render",r]]);export{k as __pageData,g as default};
